#!/usr/bin/env bash
set -euo pipefail
root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../../.." && pwd)"; work_dir="$(mktemp -d /tmp/structured_draft_materialization_XXXXXX)"; data_dir="$work_dir/data"; socket_dir="$work_dir/socket"; database="structured_draft_materialization"; port=55468; server_pid=""
mkdir -p "$socket_dir"
cleanup(){ status=$?; if [[ -n "$server_pid" ]] && kill -0 "$server_pid" 2>/dev/null; then kill "$server_pid" 2>/dev/null || true; wait "$server_pid" 2>/dev/null || true; fi; rm -rf "$work_dir"; printf 'CLEANUP_VERIFIED materialization_fixture_removed=true\n'; exit "$status"; }; trap cleanup EXIT
[[ "$(id -u)" == 0 ]] || { echo 'Requires disposable root-runner only.' >&2; exit 64; }; chown -R 1000:1000 "$work_dir"; setpriv --reuid=1000 --regid=1000 --clear-groups initdb -D "$data_dir" --no-locale --encoding=UTF8 --auth-local=trust -U lovable >/dev/null
printf "listen_addresses = ''\nport = %s\nunix_socket_directories = '%s'\nshared_memory_type = mmap\ndynamic_shared_memory_type = mmap\n" "$port" "$socket_dir" >> "$data_dir/postgresql.conf"; setpriv --reuid=1000 --regid=1000 --clear-groups postgres -D "$data_dir" >/dev/null 2>&1 & server_pid=$!
for _ in $(seq 1 150); do psql --host="$socket_dir" --port="$port" --username=lovable --dbname=postgres -Atqc 'select 1' >/dev/null 2>&1 && break; sleep .1; done
createdb --host="$socket_dir" --port="$port" --username=lovable "$database"; args=(--set=ON_ERROR_STOP=1 --host="$socket_dir" --port="$port" --username=lovable --dbname="$database"); psql "${args[@]}" -f "$root/supabase/pending/tests/sales_opportunity_structured_draft_metadata_local_fixture.sql"; psql "${args[@]}" -f "$root/supabase/pending/20261009_sales_opportunity_structured_draft_metadata.sql"; psql "${args[@]}" -f "$root/supabase/pending/20261011_sales_opportunity_structured_draft_audit_location.sql"; psql "${args[@]}" -f "$root/supabase/pending/20261011_sales_opportunity_structured_draft_materialization.sql"; psql "${args[@]}" -f "$root/supabase/pending/tests/sales_opportunity_structured_draft_materialization_local_acceptance.sql"; psql "${args[@]}" -f "$root/supabase/pending/tests/sales_opportunity_structured_draft_storage_policy_local_acceptance.sql"; printf 'MATERIALIZATION_EXECUTION_COMPLETE=true\n'
